def solve(times: List[List[int]], n: int, k: int) -> int:
    # Return the time for the signal to reach every node, or -1.
    g = defaultdict(list)
    for u, v, w in times:
        g[u].append((v, w))
    dist = {}
    pq = [(0, k)]
    while pq:
        d, u = heapq.heappop(pq)
        if u in dist:
            continue
        dist[u] = d
